def ngay_doanh_thu_dinh(p, min_revenue=None):
    o = orders(p, valid=True)
    if o.empty:
        raise Unanswerable('Không có đơn hợp lệ trong kỳ')
    o['order_date'] = pd.to_datetime(o['order_date']).dt.normalize()
    doanh_thu_ngay = o.groupby('order_date')['revenue'].sum()
    if min_revenue is not None:
        doanh_thu_ngay = doanh_thu_ngay[doanh_thu_ngay >= min_revenue]
    if doanh_thu_ngay.empty:
        raise Unanswerable('Không có ngày đạt doanh thu')
    ngay_dinh = doanh_thu_ngay.idxmax()
    return ngay_dinh

