def so_sua_bim_ta(p):
    lines = C['lines'].copy()
    lines['order_date'] = pd.to_datetime(lines['order_date'])
    mask = p.mask(lines['order_date'])
    lines = lines[mask]
    bim_ta = lines[lines['item_group'] == 'bỉm tã']
    total_qty = bim_ta['qty_base'].sum()
    if total_qty == 0:
        return pd.DataFrame()
    result = bim_ta[['item_name', 'brand', 'size', 'qty_base']].copy()
    result['percent'] = (result['qty_base'] / total_qty) * 100
    return result[['item_name', 'brand', 'size', 'percent']].sort_values('percent', ascending=False)

